// This is a simple interface which specifies echo.Route addition functions which
// are present on both echo.Echo and echo.Group, since we want to allow using
// either of them for path registration
type EchoRouter interface {
	CONNECT(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	DELETE(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	GET(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	HEAD(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	OPTIONS(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	PATCH(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	POST(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	PUT(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	TRACE(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
}

// RegisterHandlers adds each server route to the EchoRouter.
func RegisterHandlers(router EchoRouter, si ServerInterface) {
	RegisterHandlersWithBaseURL(router, si, "")
}

// Registers handlers, and prepends BaseURL to the paths, so that the paths
// can be served under a prefix.
func RegisterHandlersWithBaseURL(router EchoRouter, si ServerInterface, baseURL string) {

	wrapper := ServerInterfaceWrapper{
		Handler: si,
	}

	router.POST(baseURL+"/auth/login", wrapper.PostAuthLogin)
	router.POST(baseURL+"/auth/logout", wrapper.PostAuthLogout)
	router.POST(baseURL+"/auth/refresh", wrapper.PostAuthRefresh)
	router.POST(baseURL+"/auth/register", wrapper.PostAuthRegister)
	router.GET(baseURL+"/boards", wrapper.GetBoards)
	router.POST(baseURL+"/boards", wrapper.PostBoards)
	router.DELETE(baseURL+"/boards/:boardId", wrapper.DeleteBoardsBoardId)
	router.GET(baseURL+"/boards/:boardId", wrapper.GetBoardsBoardId)
	router.PATCH(baseURL+"/boards/:boardId", wrapper.PatchBoardsBoardId)
	router.GET(baseURL+"/boards/:boardId/statuses", wrapper.GetBoardsBoardIdStatuses)
	router.POST(baseURL+"/boards/:boardId/statuses", wrapper.PostBoardsBoardIdStatuses)
	router.GET(baseURL+"/boards/:boardId/tasks", wrapper.GetBoardsBoardIdTasks)
	router.POST(baseURL+"/boards/:boardId/tasks", wrapper.PostBoardsBoardIdTasks)
	router.GET(baseURL+"/roles", wrapper.GetRoles)
	router.POST(baseURL+"/roles", wrapper.PostRoles)
	router.DELETE(baseURL+"/roles/:roleId", wrapper.DeleteRolesRoleId)
	router.GET(baseURL+"/roles/:roleId", wrapper.GetRolesRoleId)
	router.PATCH(baseURL+"/roles/:roleId", wrapper.PatchRolesRoleId)
	router.DELETE(baseURL+"/statuses/:statusId", wrapper.DeleteStatusesStatusId)
	router.GET(baseURL+"/statuses/:statusId", wrapper.GetStatusesStatusId)
	router.PATCH(baseURL+"/statuses/:statusId", wrapper.PatchStatusesStatusId)
	router.DELETE(baseURL+"/tasks/:taskId", wrapper.DeleteTasksTaskId)
	router.GET(baseURL+"/tasks/:taskId", wrapper.GetTasksTaskId)
	router.PATCH(baseURL+"/tasks/:taskId", wrapper.PatchTasksTaskId)
	router.GET(baseURL+"/tasks/:taskId/history", wrapper.GetTasksTaskIdHistory)
	router.GET(baseURL+"/users", wrapper.GetUsers)
	router.POST(baseURL+"/users", wrapper.PostUsers)
	router.GET(baseURL+"/users/me", wrapper.GetUsersMe)
	router.PATCH(baseURL+"/users/me", wrapper.PatchUsersMe)
	router.DELETE(baseURL+"/users/:userId", wrapper.DeleteUsersUserId)
	router.GET(baseURL+"/users/:userId", wrapper.GetUsersUserId)
	router.PATCH(baseURL+"/users/:userId", wrapper.PatchUsersUserId)
	router.PATCH(baseURL+"/users/:userId/password", wrapper.PatchUsersUserIdPassword)

}
